TLM.f("Tempora/Quadp3-6",{"officium":"Sabbato post Cineres","rule":["no Gloria","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;","Super populum"],"ruleInherited":["no Gloria","Credo","Prefatio=Trinitate","Suffr=Maria2;Sanctorum,Ecclesiæ;;"],"fallback":"Tempora/Quadp3-0","from":{"GradualeF":"Tempora/Quadp3-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 29:11"},{"k":"text","la":"Audívit Dóminus, et misértus est mihi: Dóminus factus est adjútor meus."},{"k":"ref","la":"Ps 29:2"},{"k":"text","la":"Exaltábo te, Dómine, quóniam suscepísti me: nec delectásti inimícos meos super me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Audívit Dóminus, et misértus est mihi: Dóminus factus est adjútor meus."}],"Oratio":[{"k":"text","la":"Adésto, Dómine, supplicatiónibus nostris: et concéde; ut hoc sollémne jejúnium, quod animábus corporibúsque curándis salúbriter institútum est, devóto servítio celebrémus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ."},{"k":"ref","la":"Isa 58:9-14"},{"k":"text","la":"Hæc dicit Dóminus Deus: Si abstúleris de médio tui caténam, et desíeris exténdere dígitum, et loqui quod non prodest. Cum effúderis esuriénti ánimam tuam, et ánimam afflíctam repléveris, oriétur in ténebris lux tua, et ténebræ tuæ erunt sicut merídies. Et réquiem tibi dabit Dóminus semper, et implébit splendóribus ánimam tuam, et ossa tua liberábit, et eris quasi hortus irríguus, et sicut fons aquárum, cujus non defícient aquæ. Et ædificabúntur in te desérta sæculórum: fundaménta generatiónis et generatiónis suscitábis: et vocáberis ædificátor sépium, avértens sémitas in quiétem. Si avérteris a sábbato pedem tuum, fácere voluntátem tuam in die sancto meo, et vocáveris sábbatum delicátum, et sanctum Dómini gloriósum, et glorificáveris eum, dum non facis vias tuas, et non invénitur volúntas tua, ut loquáris sermónem: tunc delectáberis super Dómino: et sustóllam te super altitúdines terræ, et cibábo te hereditáte Jacob, patris tui. Os enim Dómini locútum est."}],"Graduale":[{"k":"ref","la":"Ps 26:4"},{"k":"text","la":"Unam pétii a Dómino, hanc requíram, ut inhábitem in domo Dómini,"},{"k":"text","la":"Ut vídeam voluptátem Dómini, et prótegar a templo sancto ejus.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 76:15; 76:16"},{"k":"text","la":"Tu es Deus qui facis mirabília solus: notam fecísti in géntibus virtútem tuam."},{"k":"text","la":"Liberásti in bráchio tuo pópulum tuum, fílios Israël et Joseph.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum."},{"k":"ref","la":"Marc 6:47-56"},{"k":"text","la":"In illo témpore: Cum sero esset, erat navis in médio mari, et Jesus solus in terra. Et videns discípulos suos laborántes in remigándo - erat enim ventus contrárius eis, - et circa quartam vigíliam noctis venit ad eos ámbulans supra mare: et volébat præteríre eos. At illi, ut vidérunt eum ambulántem supra mare, putavérunt phantásma esse, et exclamavérunt. Omnes enim vidérunt eum, et conturbáti sunt. Et statim locútus est cum eis, et dixit eis: Confídite, ego sum, nolíte timére. Et ascéndit ad illos in navim, et cessávit ventus. Et plus magis intra se stupébant: non enim intellexérunt de pánibus: erat enim cor eórum obcæcátum. Et cum transfretássent, venérunt in terram Genésareth, et applicuérunt. Cumque egréssi essent de navi, contínuo cognovérunt eum: et percurréntes univérsam regiónem illam, cœpérunt in grabátis eos, qui se male habébant, circumférre ubi audiébant eum esse. Et quocúmque introíbat, in vicos vel in villas aut civitátes, in platéis ponébant infírmos, et deprecabántur eum, ut vel fímbriam vestiménti ejus tángerent: et quotquot tangébant eum, salvi fiébant."}],"Offertorium":[{"k":"ref","la":"Ps 118:154 ; 118:125"},{"k":"text","la":"Dómine, vivífica me secúndum elóquium tuum: ut sciam testimónia tua."}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, sacrifícium, cujus te voluísti dignánter immolatióne placári: præsta, quǽsumus; ut, hujus operatióne mundáti, beneplácitum tibi nostræ mentis offerámus afféctum."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 2:11-12"},{"k":"text","la":"Servite Dómino in timóre, et exsultáte ei cum tremóre: apprehéndite disciplínam, ne pereátis de via justa."}],"Postcommunio":[{"k":"text","la":"Cœléstis vitæ múnere vegetáti, quǽsumus, Dómine: ut, quod est nobis in præsénti vita mystérium, fiat æternitátis auxílium."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Fidéles tui, Deus, per tua dona firméntur: ut éadem et percipiéndo requírant, et quæréndo sine fine percípiant."},{"k":"macro","name":"Per Dominum"}]},"hr":{"b35396e89743b495":{"t":"Ps 29, 11, Ps 29, 2\n(Ps 29, 11) Gospodin me je čuo i smilovao se meni. Gospodin je postao moj pomoćnik. (Ps 29, 2) Veličat ću te, Gospodine, jer si me odabrao, nisi dao da se moji neprijatelji raduju nada mnom.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 29, 11) Gospodin me je čuo i smilovao se meni. Gospodin je postao moj pomoćnik."},"f7a0ad57dc9bd42e":{"t":"<i>Pomolimo se</i>.\nMilostiv budi, Gospodine, našim molitvama i daj da ovaj svečani post koji je spasonosno ustanovljen za zdravlje duše i tijela izvršavamo odanom pokornošću.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"5920cbd38389df99":{"t":"Iz 58, 9-14\nČitanje Izaije proroka. Ovo govori Gospodin Bog: Ako zbaciš sa sebe okove, prestaneš pružati prst i govoriti zlo, pa otvoriš svojeg srce gladnome i nasitiš nevoljnika, zasjat će i u mraku tvoje svjetlo, nestat će tame i bit će kao podne. Gospodin će ti osigurati trajan mir, prosvijetlit će ti dušu i okrijepiti tvoje kosti, bit ćeš kao natopljen vrt i kao izvor kojemu ne ponestaje vode. Po pustim mjestima podizat ćeš zgrade, utvrdit ćeš temelje do posljednjih naraštaja koji će te zvati da si graditelj ograda i donosilac mira na putovima. Ako ne oskvrneš subote i ne sagriješiš u dan meni posvećen, i ako budeš poštovao subotu kao dan radosti i posvećen na Gospodnju slavu i ako ga budeš cijenio i ne budeš zašao na krive putove, te ne budeš vršio svoje volje i ne budeš govorio zla. Gospodin će biti tvoja slast i uzvisit će te nad zemaljske veličine i obdari će te baštinom tvog oca Jakova. Gospodin je to rekao."},"67101eda04fcfe91":{"t":"Ps 26, 4\nJedno samo molim od Gospodina, samo ovo tražim: da stanujem u domu Gospodnjem, da gledam ljupkost Gospodnju da se sklonim u sveti hram njegov."},"10d3b3198cdb596d":{"t":"Mk 6, 47-56\nSlijedi sveto Evanđelje po Marku. U ono vrijeme kad se spustila večer, lađa je bila na pučini, a sam je Isus bio na kopnu. Tad vidje kako se njegovi učenici muče veslajući jer je puhao protivan vjetar. Oko četvrte noćne straže idući po moru dođe do njih i htjede ih mimoići. A kad ga oni opaze, da hoda po moru, pomisliše da je sablast i povikaše, jer ga svi vidješe i preplašiše se. On im odmah prozbori i reče: Smirite se, nemojte se bojati! Tada uđe k njima u lađu, i vjetar prestane. Oni su se to više začudili, jer još nisu bili shvatili čuda s kruhom. Njihovo je srce bilo zaslijepljeno. Kad su preplovili more, pristanu u zemlji Genezaret. A kad su izašli iz lađe, ljudi ga prepoznaše, pa prođu onim krajevima i gdje su čuli da je on, donosili su na ležajima bolesnike. I u koje je god selo, grad ili naselje ulazio, postavljali su bolesnike na putove i molili ga da se dotaknu barem okrajka njegove haljine, te su ozdravljali svi koji su ga se dotakli."},"e377320db8d2b6d1":{"t":"Ps 118, 154 i 125\nOživi me, Gospodine, po riječi tvojoj, utisni mi u srce naredbe svoje."},"c41df56ce19dd826":{"t":"Primi, Gospodine, žrtvu kojom si se blagonaklono htio pomiriti, i daj nam, molimo te, da očišćeni njezinim djelovanjem prinesemo tebi prijatan osjećaj svoje duše.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"0f5686ae25f2ecdf":{"t":"Ps 2, 11-12\nSlužite Gospodinu u strahopoštovanju, kličite mu u predanju duše, prihvatite njegovu nauku da ne skrenete s pravog puta."},"16560c47d5170e4a":{"t":"<i>Pomolimo se</i>.\nNahranjeni darom nebeskog života, molimo, Gospodine, da nam ono što nam je u sadašnjem životu tajna, bude pomoć za vječnost.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"b37f7e3a173da092":{"t":"<i>Pomolimo se</i>.\nVjernici tvoji, Bože, neka se tvojim darovima učvrste, da ih primajući traže i tražeći ih uvijek primaju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
